def prune(self, other: DataTree) -> DataTree:
    \"\"\"
    Prune this DataTree to be isomorphic to a subset of another DataTree.

    Parameters
    ----------
    other : DataTree
        The DataTree to prune against.

    Returns
    -------
    DataTree
        A new DataTree containing only the nodes and structure common to both.
    \"\"\"
    self_paths = {path for path, _ in self.subtree_with_keys}
    other_paths = {path for path, _ in other.subtree_with_keys}
    common_paths = self_paths & other_paths

    new_dt = DataTree()
    for path, node in self.subtree_with_keys:
        if path in common_paths:
            if path == \"\":
                new_dt.data = node.data
            else:
                new_dt[path] = node.data
    return new_dt
